-- Isolated local Schnitzery staging only. All fixture rows and journals roll back.
\set ON_ERROR_STOP on
begin;
create temp table ops_fixture(a uuid,b uuid,manager uuid,other_manager uuid,staff uuid,supplier uuid,p1 uuid,p2 uuid,po uuid,transfer uuid,waste uuid,receipt uuid);
insert into ops_fixture select gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid();
grant select on ops_fixture to authenticated;
insert into public.branches(id,name) select a,'Operations test A' from ops_fixture union all select b,'Operations test B' from ops_fixture;
insert into auth.users(id,email) select manager,manager::text||'@ops.example.invalid' from ops_fixture union all select other_manager,other_manager::text||'@ops.example.invalid' from ops_fixture union all select staff,staff::text||'@ops.example.invalid' from ops_fixture;
insert into public.users(id,branch_id,role,status,full_name) select manager,a,'manager','active','Synthetic A manager' from ops_fixture union all select other_manager,b,'manager','active','Synthetic B manager' from ops_fixture union all select staff,a,'staff','active','Synthetic staff' from ops_fixture
on conflict(id) do update set branch_id=excluded.branch_id,role=excluded.role,status=excluded.status;
select set_config('request.jwt.claim.sub',manager::text,true) from ops_fixture;
set local role authenticated;
do $$ declare f record; body jsonb; r jsonb; cmd uuid:=gen_random_uuid(); l1 uuid; l2 uuid; n integer; original jsonb; replacement uuid; begin
 select * into f from ops_fixture;
 body:=jsonb_build_object('id',f.supplier,'revision',0,'name','Synthetic supplier','email','orders@example.invalid','lead_days',3,'is_active',true);
 perform public.inventory_operation(f.a,cmd,'supplier_save',body);
 perform public.inventory_operation(f.a,cmd,'supplier_save',body);
 if (select count(*) from public.inventory_suppliers where branch_id=f.a)<>1 then raise exception 'Duplicate supplier'; end if;
 begin perform public.inventory_operation(f.b,gen_random_uuid(),'supplier_save',body);raise exception 'Cross branch accepted';exception when insufficient_privilege then null;end;
 perform public.inventory_operation(f.a,gen_random_uuid(),'product_save',jsonb_build_object('id',f.p1,'revision',0,'product','Rice','category','Dry','unit','kg','soll',10,'reorder_point',3,'reorder_qty',5,'supplier_id',f.supplier));
 perform public.inventory_operation(f.a,gen_random_uuid(),'product_save',jsonb_build_object('id',f.p2,'revision',0,'product','Oil','category','Dry','unit','l','soll',6));
 if not exists(select 1 from public.inventory_master where id=f.p1 and reorder_point=3 and reorder_qty=5) then raise exception 'Settings not saved';end if;
 begin update public.inventory_master set unit='pack' where id=f.p1;raise exception 'History identity rewrite allowed';exception when raise_exception then if sqlerrm='History identity rewrite allowed' then raise;end if;end;
 body:=jsonb_build_object('id',f.po,'revision',0,'supplier_id',f.supplier,'note','Weekly order','lines',jsonb_build_array(jsonb_build_object('product_id',f.p1,'qty',10,'unit_price',0.005),jsonb_build_object('product_id',f.p2,'qty',4,'unit_price',null)));
 perform public.inventory_operation(f.a,gen_random_uuid(),'po_save',body);
 select id into l1 from public.inventory_order_lines where order_id=f.po and product_id=f.p1;
 select id into l2 from public.inventory_order_lines where order_id=f.po and product_id=f.p2;
 if (select unit_price from public.inventory_order_lines where id=l1)<>0.005 then raise exception 'Fractional price lost';end if;
 if (select unit_price from public.inventory_order_lines where id=l2) is not null then raise exception 'Unknown price became zero';end if;
 begin update public.inventory_orders set status='sent' where id=f.po;raise exception 'Direct order write allowed';exception when insufficient_privilege then null;end;
 begin perform public.inventory_operation(f.a,gen_random_uuid(),'po_send',jsonb_build_object('id',f.po,'revision',0,'note','External email'));raise exception 'Approval skipped';exception when raise_exception then if sqlerrm='Approval skipped' then raise;end if;end;
 perform public.inventory_operation(f.a,gen_random_uuid(),'po_approve',jsonb_build_object('id',f.po,'revision',0));
 begin perform public.inventory_operation(f.a,gen_random_uuid(),'po_cancel',jsonb_build_object('id',f.po,'revision',0,'note','Stale tab'));raise exception 'Stale revision accepted';exception when serialization_failure then null;end;
 perform public.inventory_operation(f.a,gen_random_uuid(),'po_send',jsonb_build_object('id',f.po,'revision',1,'note','Sent manually via supplier email'));
 body:=jsonb_build_object('id',f.po,'revision',2,'invoice','Delivery-1','lines',jsonb_build_array(jsonb_build_object('id',l1,'accepted',6,'rejected',1,'cost',0.03,'note','Partial shipment, one damaged'),jsonb_build_object('id',l2,'accepted',2,'rejected',0,'cost',8,'note','Partial shipment')));
 perform public.inventory_operation(f.a,f.receipt,'receive',body);
 perform public.inventory_operation(f.a,f.receipt,'receive',body);
 if (select status from public.inventory_orders where id=f.po)<>'partial' then raise exception 'Partial status missing';end if;
 if (select count(*) from public.inventory_purchases where receipt_id=f.receipt)<>2 then raise exception 'Receipt duplicate/lost lines';end if;
 if (select sum(qty) from public.inventory_purchases where receipt_id=f.receipt)<>8 then raise exception 'Rejected stock was posted';end if;
 if (select sum(cost) from public.inventory_purchases where receipt_id=f.receipt)<>8.03 then raise exception 'Actual line cost mismatch';end if;
 begin perform public.inventory_operation(f.a,gen_random_uuid(),'receive',body||jsonb_build_object('revision',3));raise exception 'Duplicate delivery reference accepted';exception when unique_violation then null;end;
 -- Every receipt is atomic: one valid line followed by an invalid identity rolls everything back.
 body:=jsonb_build_object('id',f.po,'revision',3,'invoice','Bad delivery','lines',jsonb_build_array(jsonb_build_object('id',l1,'accepted',4,'rejected',0,'cost',2,'note',''),jsonb_build_object('id',gen_random_uuid(),'accepted',1,'rejected',0,'cost',1,'note','')));
 begin perform public.inventory_operation(f.a,gen_random_uuid(),'receive',body);raise exception 'Foreign receipt line accepted';exception when raise_exception then if sqlerrm='Foreign receipt line accepted' then raise;end if;end;
 if (select received_qty from public.inventory_order_lines where id=l1)<>6 then raise exception 'Failed receipt leaked quantity';end if;
 if exists(select 1 from public.inventory_receipts where order_id=f.po and invoice='Bad delivery') then raise exception 'Failed receipt left header';end if;
 body:=jsonb_build_object('id',f.po,'revision',3,'invoice','Delivery-2','lines',jsonb_build_array(jsonb_build_object('id',l1,'accepted',4,'rejected',0,'cost',2,'note',''),jsonb_build_object('id',l2,'accepted',2,'rejected',0,'cost',8,'note','')));
 perform public.inventory_operation(f.a,gen_random_uuid(),'receive',body);
 if (select status from public.inventory_orders where id=f.po)<>'closed' then raise exception 'Final receipt did not close';end if;
 -- Renaming/unit changes create a replacement; frozen order lines keep their old identity.
 r:=public.inventory_operation(f.a,gen_random_uuid(),'product_save',jsonb_build_object('id',f.p1,'revision',0,'product','Rice packs','category','Dry','unit','pack','soll',5));
 replacement:=(r->>'id')::uuid;
 if replacement=f.p1 or (select is_active from public.inventory_master where id=f.p1) then raise exception 'Replacement not archived';end if;
 if (select unit from public.inventory_order_lines where id=l1)<>'kg' then raise exception 'Historical unit rewritten';end if;
 insert into public.waste_log(id,branch_id,product,category,qty,unit,reason,logged_by,work_date) values(f.waste,f.a,'Oil','Dry',3,'l','spoiled',f.manager,current_date);
 select to_jsonb(w) into original from public.waste_log w where id=f.waste;
 body:=jsonb_build_object('id',f.waste,'qty',2,'before',original,'note','Entry was overstated');cmd:=gen_random_uuid();
 perform public.inventory_operation(f.a,cmd,'waste_correct',body);perform public.inventory_operation(f.a,cmd,'waste_correct',body);
 begin perform public.inventory_operation(f.a,gen_random_uuid(),'waste_correct',body);raise exception 'Stale waste correction accepted';exception when serialization_failure then null;end;
 select to_jsonb(w) into original from public.waste_log w where id=f.waste;
 perform public.inventory_operation(f.a,gen_random_uuid(),'waste_correct',jsonb_build_object('id',f.waste,'qty',0,'before',original,'note','Duplicate log, void it'));
 if exists(select 1 from public.waste_log where id=f.waste) then raise exception 'Void did not remove current record';end if;
 if (select count(*) from public.stock_events where source_id=f.waste)<>3 then raise exception 'Waste evidence lost';end if;
 insert into public.stock_transfers(id,from_branch_id,to_branch_id,product,category,unit,qty,requested_by) values(f.transfer,f.b,f.a,'Oil','Dry','l',10,f.manager);
 begin update public.stock_transfers set status='sent' where id=f.transfer;raise exception 'Destination dispatched transfer';exception when insufficient_privilege then null;end;
 raise notice 'PASS: supplier/product settings, preserved identities, order lifecycle, price precision, partial multi-line receipts, atomic rollback, retries, revisions, waste correction/void evidence';
end $$;
reset role;
select set_config('request.jwt.claim.sub',other_manager::text,true) from ops_fixture;
set local role authenticated;
update public.stock_transfers set status='sent' where id=(select transfer from ops_fixture);
do $$ declare f record;begin select * into f from ops_fixture;
 if exists(select 1 from public.inventory_orders where branch_id=f.a) then raise exception 'Other branch can read order';end if;
 begin update public.stock_transfers set status='received',received_qty=10 where id=f.transfer;raise exception 'Source received own dispatch';exception when insufficient_privilege then null;end;
end $$;
reset role;
select set_config('request.jwt.claim.sub',manager::text,true) from ops_fixture;
set local role authenticated;
do $$ declare f record;begin select * into f from ops_fixture;
 perform public.inventory_operation(f.a,gen_random_uuid(),'transfer_receive',jsonb_build_object('id',f.transfer,'qty',8,'note','Two litres damaged in transit'));
 if (select received_qty from public.stock_transfers where id=f.transfer)<>8 then raise exception 'Actual receipt quantity lost';end if;
 begin update public.stock_transfers set received_qty=10 where id=f.transfer;raise exception 'Closed receipt edited';exception when serialization_failure then null;end;
 raise notice 'PASS: transfer side authorization, actual shortage receipt, immutable closed receipt';
end $$;
reset role;
select set_config('request.jwt.claim.sub',staff::text,true) from ops_fixture;
set local role authenticated;
do $$ declare f record;begin select * into f from ops_fixture;
 if exists(select 1 from public.inventory_orders) or exists(select 1 from public.inventory_suppliers) or exists(select 1 from public.inventory_operation_events) then raise exception 'Staff reads manager inventory data';end if;
 begin perform private.inventory_operation(f.a,gen_random_uuid(),'supplier_save','{}');raise exception 'Staff mutation allowed';exception when insufficient_privilege then null;end;
 raise notice 'PASS: staff RLS and private RPC authorization';
end $$;
reset role;
-- All Schnitzery branches are visible to brand owners; staff and inactive accounts are not managers.
select set_config('request.jwt.claim.sub','',true);
update public.users set role='brand_owner' where id=(select manager from ops_fixture);
select set_config('request.jwt.claim.sub',manager::text,true) from ops_fixture;
set local role authenticated;
do $$declare f record;begin select * into f from ops_fixture;
 if not exists(select 1 from public.inventory_orders where id=f.po) then raise exception 'Owner lost order access';end if;
 if not exists(select 1 from public.accessible_branch_ids() b where b=f.b) then raise exception 'Owner lost branch access';end if;
 raise notice 'PASS: owner branch visibility';end $$;
reset role;
select set_config('request.jwt.claim.sub','',true);
update public.users set status='inactive' where id=(select manager from ops_fixture);
select set_config('request.jwt.claim.sub',manager::text,true) from ops_fixture;
set local role authenticated;
do $$declare f record;begin select * into f from ops_fixture;
 if exists(select 1 from public.inventory_orders) or exists(select 1 from public.inventory_operation_events) then raise exception 'Inactive owner can read inventory operations';end if;
 begin perform public.inventory_operation(f.a,gen_random_uuid(),'supplier_save','{}');raise exception 'Inactive owner can mutate';exception when insufficient_privilege then null;end;
 raise notice 'PASS: inactive owner read/write denial';end $$;
reset role;
rollback;
